using System;
using System.Linq;
using System.Drawing;
using System.Collections.Generic;
using Grasshopper.Kernel;
using Grasshopper.Kernel.Types;
using Grasshopper.Kernel.Data;
using Rhino;
using Rhino.Geometry;
namespace PlugInSolar {
public sealed class PvExposureMapComponent:GH_Component {
 public PvExposureMapComponent():base("PV Exposure Map","Exposure Map","Compare panel-average irradiation or inspect cell shading from PV Energy Calculator. Default scale spans the minimum and maximum cells across all supplied results. Connect multiple layouts directly; all input branches automatically share one scale; no solar calculation is repeated. Required inputs: Solar Exposure Results.","Pika","04 Visualization"){}
 public override Guid ComponentGuid=>new Guid("1d98fa40-7f70-47da-a892-f70ed79c2403");protected override Bitmap Icon=>Assets.Icon("irradiance");
 protected override void RegisterInputParams(GH_InputParamManager p){p.AddGenericParameter("Solar Exposure Results","Results","PV Energy Calculator → Solar Exposure Results. Connect multiple outputs directly. All branches are collected automatically into one comparison. All results must cover the same timestamps.",GH_ParamAccess.tree);int a=p.AddNumberParameter("Legend Minimum","Min","Optional fixed minimum in kWh/m². Defaults to the lowest cell irradiation across all supplied results. Pair with Maximum to compare alternatives using one scale.",GH_ParamAccess.item);p[a].Optional=true;int b=p.AddNumberParameter("Legend Maximum","Max","Optional fixed maximum in kWh/m². Default is the highest cell irradiation across the supplied results, shared by both display modes.",GH_ParamAccess.item);p[b].Optional=true;int c=p.AddPlaneParameter("Legend Plane","Plane","Optional location and orientation for the legend. Default places it beside the analysis geometry.",GH_ParamAccess.item);p[c].Optional=true;p.AddBooleanParameter("Cell Detail","Cells","False: one average irradiation color per panel. True: individual cell colors for shading inspection. Both modes use the same scale. Defaults to True.",GH_ParamAccess.item,true);}
 protected override void RegisterOutputParams(GH_OutputParamManager p){p.AddMeshParameter("Exposure Map","Map","Panel meshes colored by panel average or individual cells. Blue = lower, red = higher period irradiation. Units kWh/m².",GH_ParamAccess.list);p.AddGeometryParameter("Legend","Legend","Color bar, numeric ticks, units and supplied-period label. Default size follows the analysis geometry.",GH_ParamAccess.list);p.AddNumberParameter("Cell Irradiation","Cell H","kWh/m², branch {panel index}, in cell/mesh-face order. Connect to a custom spatial heatmap with Analysis Mesh.",GH_ParamAccess.tree);p.AddMeshParameter("Analysis Mesh","Mesh","Uncolored analysis cells corresponding exactly to Cell Irradiation values.",GH_ParamAccess.list);p.AddNumberParameter("Chart Values","Values","Panel-average period irradiation, kWh/m²; connect with Chart Labels to bar charts.",GH_ParamAccess.list);p.AddTextParameter("Chart Labels","Labels","Panel IDs aligned with Chart Values.",GH_ParamAccess.list);p.AddTextParameter("Summary Data","Summary","CSV rows: panel ID, area m², irradiation kWh/m², incident solar kWh, irradiation reduction %. Not electricity.",GH_ParamAccess.list);p.AddTextParameter("Report","Report","Legend limits, time period and interpretation. Time indexing remains inside grouped Results.",GH_ParamAccess.item);}
 public static Mesh PanelMesh(PvExposureResult r,int i,bool colored,double min,double max,bool cellDetail=true){var m=new Mesh();for(int j=0;j<r.CellVertices[i].Length;j++){var v=r.CellVertices[i][j];int k=m.Vertices.Count;for(int z=0;z<4;z++)m.Vertices.Add(v[z*3],v[z*3+1],v[z*3+2]);m.Faces.AddFace(k,k+1,k+2,k+3);if(colored){var c=Ramp(((cellDetail?r.CellIrradiation[i][j]:r.Irradiation[i])-min)/(max-min));for(int z=0;z<4;z++)m.VertexColors.Add(c);}}m.Normals.ComputeNormals();return m;}
 public static Color Ramp(double q){q=Math.Max(0,Math.Min(1,q));var colors=new[]{Color.FromArgb(45,70,200),Color.FromArgb(60,175,235),Color.FromArgb(255,245,160),Color.FromArgb(250,140,35),Color.FromArgb(200,35,30)};double p=q*4;int i=Math.Min(3,(int)p);double x=p-i;return Color.FromArgb((int)(colors[i].R*(1-x)+colors[i+1].R*x),(int)(colors[i].G*(1-x)+colors[i+1].G*x),(int)(colors[i].B*(1-x)+colors[i+1].B*x));}
 protected override void SolveInstance(IGH_DataAccess da){try{foreach(var output in Params.Output)output.ClearData();
 GH_Structure<IGH_Goo> tree; if(!da.GetDataTree(0,out tree))return;
 var inputs=tree.AllData(true).ToList();if(inputs.Count==0)return;
 if(inputs.Any(x=>x==null))throw new ArgumentException("An input result is empty. Resolve upstream calculation errors.");
 var results=inputs.Select(x=>PvPanelCatalog.Unwrap<PvExposureData>(x).Data).ToList();
 foreach(var item in results){if(item.CellIrradiation==null||item.CellVertices==null)throw new ArgumentException("Results have no grid cells. Recalculate using PV Energy Calculator.");if(!item.Timestamps.SequenceEqual(results[0].Timestamps))throw new ArgumentException("All compared layouts must use the same analysis timestamps.");}
 bool detail=true;da.GetData(4,ref detail);
 var values=results.SelectMany(x=>x.CellIrradiation).SelectMany(x=>x).ToArray();
 double min=values.Min(),max=values.Max();bool fixedMin=da.GetData(1,ref min),fixedMax=da.GetData(2,ref max);
 if(min==max&&!fixedMin&&!fixedMax){double pad=Math.Max(.01,Math.Abs(min)*.01);min=Math.Max(0,min-pad);max+=pad;}
 PvSeries.Check(min,"Legend minimum",0);PvSeries.Check(max,"Legend maximum",0);
 if(max<=min)throw new ArgumentException("Legend Maximum must exceed Minimum.");
 var r=new PvExposureResult {
 Ids=results.SelectMany((x,k)=>x.Ids.Select(id=>results.Count>1?"Layout"+(k+1)+"/"+id:id)).ToArray(),
 Timestamps=results[0].Timestamps,
 CellVertices=results.SelectMany(x=>x.CellVertices).ToArray(),CellIrradiation=results.SelectMany(x=>x.CellIrradiation).ToArray(),
 Irradiation=results.SelectMany(x=>x.Irradiation).ToArray(),AreaM2=results.SelectMany(x=>x.AreaM2).ToArray(),ShadingReductionPct=results.SelectMany(x=>x.ShadingReductionPct).ToArray()
 };

 var colored=new List<Mesh>();var raw=new List<Mesh>();var bounds=BoundingBox.Empty;for(int i=0;i<r.Ids.Length;i++){colored.Add(PanelMesh(r,i,true,min,max,detail));raw.Add(PanelMesh(r,i,false,min,max));bounds.Union(raw[i].GetBoundingBox(true));}double size=Math.Max(bounds.Diagonal.Length*.12,1e-3);Plane plane=new Plane(new Point3d(bounds.Max.X+size*.5,bounds.Min.Y,bounds.Min.Z),Vector3d.XAxis,Vector3d.ZAxis);da.GetData(3,ref plane);if(!plane.IsValid)throw new ArgumentException("Legend Plane is invalid.");var legend=new List<GeometryBase>();
 for(int k=0;k<6;k++){double y=k*size*.35;var mesh=new Mesh();foreach(var pt in new[]{plane.PointAt(0,y),plane.PointAt(size*.2,y),plane.PointAt(size*.2,y+size*.35),plane.PointAt(0,y+size*.35)})mesh.Vertices.Add(pt);mesh.Faces.AddFace(0,1,2,3);mesh.VertexColors.CreateMonotoneMesh(Ramp(k/5d));legend.Add(mesh);var text=new TextEntity{Plane=new Plane(plane.PointAt(size*.28,y),plane.XAxis,plane.YAxis),TextHeight=size*.13,PlainText=(min+(max-min)*k/5).ToString("0.###",System.Globalization.CultureInfo.InvariantCulture)};legend.Add(text);}
 legend.Add(new TextEntity{Plane=new Plane(plane.PointAt(0,size*2.3),plane.XAxis,plane.YAxis),TextHeight=size*.14,PlainText="Solar irradiation [kWh/m²]\nSupplied analysis hours"});da.SetDataList(0,colored);da.SetDataList(1,legend);da.SetDataTree(2,PvDataTrees.Numbers(r.CellIrradiation));da.SetDataList(3,raw);da.SetDataList(4,r.Irradiation);da.SetDataList(5,r.Ids);var rows=new List<string>{"Panel ID,Area m2,Irradiation kWh/m2,Incident solar kWh,Irradiation reduction %"};for(int i=0;i<r.Ids.Length;i++)rows.Add("\""+r.Ids[i].Replace("\"","\"\"")+"\","+string.Join(",",new[]{r.AreaM2[i],r.Irradiation[i],r.AreaM2[i]*r.Irradiation[i],r.ShadingReductionPct[i]}.Select(x=>x.ToString("G17",System.Globalization.CultureInfo.InvariantCulture))));da.SetDataList(6,rows);da.SetData(7,$"{values.Length} analysis cells; legend {min:0.###}–{max:0.###} kWh/m². {r.Timestamps.Length} hourly records. Display: {(detail?"cell detail":"panel average")}. Shared scale across {results.Count} supplied layouts. All input branches are combined automatically; separate map components need identical explicit limits. Colors are irradiation, not installation suitability. Incident solar energy is not electrical energy.");Message=detail?$"{values.Length} cells":$"{r.Ids.Length} panel averages";
 }catch(Exception e){foreach(var p in Params.Output)p.ClearData();Message="";AddRuntimeMessage(GH_RuntimeMessageLevel.Error,e.Message);}}
}
}
